// compile-time bounds (the full tree / coverage check is the host test's: test_qwen38_design_host.cpp)
constexpr bool bounds_ok() {
    for (uint32_t p = 0; p < kPools; ++p) {
        const Pool& q = kPool[p];
        if (q.first_work + q.n_work > kWorks || q.harvest > 16 || q.rotation >= 130) return false;
        if (p + 1 < kPools && kPool[p + 1].first_work != q.first_work + q.n_work) return false;
    }
    for (uint32_t i = 0; i < kWorks; ++i) if (kWork[i].core >= 130 || kWork[i].parent >= 130) return false;
    return true;
}
static_assert(bounds_ok(), "unit_assign: an index is out of range");

